const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const digangali = ee.Geometry.Point([15.3, 12.0]); // Approximate coordinates for Digangali, Chad
  const region = digangali.buffer(5000); // 5km buffer around point

  const date1 = '2021-09-18';
  const date2 = '2022-10-23';

  // 2. Data Acquisition - Using Sentinel-2
  function getS2Collection(date) {
    return ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
      .filterBounds(region)
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));
  }

  // Get collections for both dates
  const col1 = getS2Collection(date1);
  const col2 = getS2Collection(date2);

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`${date1} Images: ${size1}`);
  console.log(`${date2} Images: ${size2}`);

  // Check for empty collections
  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get first image from each collection
  const img1 = col1.first();
  const img2 = col2.first();

  // 3. Water detection using MNDWI
  function calculateWaterArea(img) {
    // Calculate MNDWI = (Green - SWIR1) / (Green + SWIR1)
    const mndwi = img.normalizedDifference(['B3', 'B11']).rename('MNDWI');

    // Apply cloud mask using QA60 band
    const qa = img.select('QA60');
    const cloudMask = qa.bitwiseAnd(1 << 10).or(qa.bitwiseAnd(1 << 11)).eq(0);

    // Water threshold (MNDWI > 0 typically indicates water)
    const water = mndwi.updateMask(cloudMask).gt(0);

    // Calculate water area
    const areaStats = water.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: region,
      scale: 20,
      maxPixels: 1e9
    });

    const pixelCount = water.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 20,
      maxPixels: 1e9
    });

    const waterArea = areaStats.get('MNDWI').getInfo();
    const validPixels = pixelCount.get('MNDWI').getInfo();

    return {waterArea: waterArea || 0, validPixels: validPixels || 0};
  }

  const water1 = calculateWaterArea(img1);
  const water2 = calculateWaterArea(img2);

  console.log(`${date1} Water Pixels: ${water1.waterArea}, Valid Pixels: ${water1.validPixels}`);
  console.log(`${date2} Water Pixels: ${water2.waterArea}, Valid Pixels: ${water2.validPixels}`);

  // Check for no valid pixels
  if (water1.validPixels === 0 || water2.validPixels === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (water1.waterArea === null || water2.waterArea === null || 
      isNaN(water1.waterArea) || isNaN(water2.waterArea)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 4. Compare water extent
  const change = water2.waterArea - water1.waterArea;
  const percentChange = ((change / water1.waterArea) * 100).toFixed(1);

  console.log(`Water Change: ${change.toFixed(0)} pixels (${percentChange}%)`);

  // 5. Final answer based on increase
  if (change > 0) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
